import{_ as t,c as i,m as a,a as e,t as o,a4 as r,o as h}from"./chunks/framework.CnEFexpY.js";const x=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"AI/tips.md","filePath":"AI/tips.md"}'),n={name:"AI/tips.md"},s=r('<p>提示词（Prompt）是针对大模型的输入，是用户提供的文本指令或问题，用于引导模型理解任务需求并输出符合预期的结果。类似于人类对话中的提问或指令，是大模型与用户交互的 “桥梁”。</p><h3 id="提示词的核心作用" tabindex="-1">提示词的核心作用 <a class="header-anchor" href="#提示词的核心作用" aria-label="Permalink to &quot;提示词的核心作用&quot;">​</a></h3><h4 id="任务定义" tabindex="-1">任务定义 <a class="header-anchor" href="#任务定义" aria-label="Permalink to &quot;任务定义&quot;">​</a></h4><p>明确告知模型需要执行的任务类型，例如问答、写作、翻译或编程等，确保模型能够聚焦任务需求。</p><h4 id="上下文设定" tabindex="-1">上下文设定 <a class="header-anchor" href="#上下文设定" aria-label="Permalink to &quot;上下文设定&quot;">​</a></h4><p>通过提供任务的背景信息，帮助模型理解上下文语境，从而缩小思考范围，产出更贴合需求的答案。</p><h4 id="输出控制" tabindex="-1">输出控制 <a class="header-anchor" href="#输出控制" aria-label="Permalink to &quot;输出控制&quot;">​</a></h4><p>通过格式、风格、长度等要求，精确约束生成内容的结构，确保输出内容符合预期的规范和标准。</p><h3 id="为什么提示词重要" tabindex="-1">为什么提示词重要 <a class="header-anchor" href="#为什么提示词重要" aria-label="Permalink to &quot;为什么提示词重要&quot;">​</a></h3><h4 id="提示词质量的影响" tabindex="-1">提示词质量的影响 <a class="header-anchor" href="#提示词质量的影响" aria-label="Permalink to &quot;提示词质量的影响&quot;">​</a></h4><p>大模型本质是 “无预设目标” 的概率生成器，提示词的质量直接影响输出的准确性和相关性。</p><h4 id="提示词与模型性能" tabindex="-1">提示词与模型性能 <a class="header-anchor" href="#提示词与模型性能" aria-label="Permalink to &quot;提示词与模型性能&quot;">​</a></h4><p>好的提示词能激发模型的潜力，差的提示词可能导致答非所问或低质量结果。</p><h3 id="提示词的常见类型" tabindex="-1">提示词的常见类型 <a class="header-anchor" href="#提示词的常见类型" aria-label="Permalink to &quot;提示词的常见类型&quot;">​</a></h3><h4 id="指令型" tabindex="-1">指令型 <a class="header-anchor" href="#指令型" aria-label="Permalink to &quot;指令型&quot;">​</a></h4><p>清晰明确任务指令，如 “请总结这篇文章的核心观点” 后附文章内容，引导模型专注完成任务。</p><h4 id="角色扮演型" tabindex="-1">角色扮演型 <a class="header-anchor" href="#角色扮演型" aria-label="Permalink to &quot;角色扮演型&quot;">​</a></h4><p>设定模型身份，如 “假设你是一位历史学家” 引导模型从特定视角出发，增强内容专业性。</p><h4 id="问答型" tabindex="-1">问答型 <a class="header-anchor" href="#问答型" aria-label="Permalink to &quot;问答型&quot;">​</a></h4><p>以问题形式激发模型知识探索，如 “为什么天空是蓝色的？” 促进模型与用户的知识交流。</p><h4 id="示例驱动型" tabindex="-1">示例驱动型 <a class="header-anchor" href="#示例驱动型" aria-label="Permalink to &quot;示例驱动型&quot;">​</a></h4><p>提供详尽的输入输出示例，引导模型通过 Few-shot Learning（少样本学习）模仿生成内容。</p><h4 id="结构化提示" tabindex="-1">结构化提示 <a class="header-anchor" href="#结构化提示" aria-label="Permalink to &quot;结构化提示&quot;">​</a></h4><p>结合格式要求，如 “生成包含标题、大纲和结论的演讲稿”，引导模型结构化输出信息。</p><h2 id="示例" tabindex="-1">示例： <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例：&quot;">​</a></h2><h3 id="驱动类型" tabindex="-1">驱动类型 <a class="header-anchor" href="#驱动类型" aria-label="Permalink to &quot;驱动类型&quot;">​</a></h3><h4 id="技巧" tabindex="-1">技巧 <a class="header-anchor" href="#技巧" aria-label="Permalink to &quot;技巧&quot;">​</a></h4><p>提供输入 - 输出示例，让模型模仿已知模式，助力精准生成相关内容。</p><h4 id="提示词示例" tabindex="-1">提示词示例 <a class="header-anchor" href="#提示词示例" aria-label="Permalink to &quot;提示词示例&quot;">​</a></h4><p>你是一名电商客服助手，请严格按以下示例格式回答用户关于退货的问题：<br> 【示例】<br> 用户问：“怎么退货？”<br> 回答：<br> “您好！根据我们的退货政策（条款 3.2），您需满足以下条件：</p><ol><li><strong>商品状态</strong>：未拆封、标签完好；</li><li><strong>时效</strong>：签收后 7 天内申请；</li><li><strong>操作步骤</strong>：</li></ol><ul><li>步骤 1：登录 APP，进入‘我的订单’；</li><li>步骤 2：选择订单 → 点击‘申请售后’→ 提交退货原因；</li><li>步骤 3：快递员将在 24 小时内上门取件。<br> 若您需要帮助提交申请，可回复‘转人工’为您服务哦～”</li></ul>',32),d=a("br",null,null,-1),c=a("br",null,null,-1),u=r('<h3 id="结合关键词" tabindex="-1">结合关键词 <a class="header-anchor" href="#结合关键词" aria-label="Permalink to &quot;结合关键词&quot;">​</a></h3><h4 id="技巧-1" tabindex="-1">技巧 <a class="header-anchor" href="#技巧-1" aria-label="Permalink to &quot;技巧&quot;">​</a></h4><p>在提示词中巧妙嵌入关键词，确保生成的内容与关键词紧密相关，提升准确性。</p><h4 id="提示词示例-1" tabindex="-1">提示词示例 <a class="header-anchor" href="#提示词示例-1" aria-label="Permalink to &quot;提示词示例&quot;">​</a></h4><p>提示词：<br> 客户询问耳机退货政策时，请用生活化语言解释退货条件和步骤，回复中需包含关键词：七天无理由、未拆塑封、运费险。</p><h3 id="不同场景下提示词示例" tabindex="-1">不同场景下提示词示例 <a class="header-anchor" href="#不同场景下提示词示例" aria-label="Permalink to &quot;不同场景下提示词示例&quot;">​</a></h3><h4 id="场景-2-故障处理引导" tabindex="-1">场景 2：故障处理引导 <a class="header-anchor" href="#场景-2-故障处理引导" aria-label="Permalink to &quot;场景 2：故障处理引导&quot;">​</a></h4><ul><li><strong>目标</strong>：采用共情策略，逐步引导用户检查，避免技术术语，确保沟通顺畅。</li><li><strong>提示词设计</strong>：<br> 角色：家电维修客服专家<br> 任务：根据用户描述的冰箱不制冷问题，按以下逻辑生成回复：</li></ul><ol><li>共情确认：&quot;非常理解您的不便，我们先做几个简单检查&quot;</li><li>分步骤引导（最多 3 步）：</li></ol><ul><li>步骤 1：检查电源插头是否松动</li><li>步骤 2：确认温控器是否设定在 2 - 4 档</li><li>步骤 3：听压缩机是否有嗡嗡声</li></ul><ol><li>结果判断：</li></ol><ul><li>若任一步骤发现问题 → 指导解决方法</li><li>全部正常 → 提供预约维修链接<br> 禁用词汇：故障代码、拆机、保修期外费用</li></ul>',12);function b(l,p,q,_,m,P){return h(),i("div",null,[s,a("p",null,[d,e(" 现在请回答用户问题："),c,e(" 用户问：“"+o(l.用户提问)+"”",1)]),u])}const k=t(n,[["render",b]]);export{x as __pageData,k as default};
